"""Generated by scripts/generate_fa3_tasks.py; edit the generator/templates."""
import math
import torch

BATCH_SIZE = 1
NUM_HEADS = 16
NUM_KV_HEADS = 16
SEQ_LEN_Q = 4096
SEQ_LEN_K = 4096
HEAD_DIM = 64
DTYPE = torch.float16
CAUSAL = False
BACKWARD = True
SPLIT = False
BLOCK_M = 128
SCALE = 1.0 / math.sqrt(HEAD_DIM)
FUNCTION_SIGNATURE = 'void launch_fa3_bwd(\n    const void* Q,\n    const void* K,\n    const void* V,\n    const void* O,\n    const void* dO,\n    void* dQ,\n    void* dK,\n    void* dV,\n    const float* lse,\n    float* dsoftmax_sum,\n    float* dq_accum,\n    int B,\n    int H,\n    int Sq,\n    int Sk,\n    int D,\n    float scale,\n    cudaStream_t stream\n);'
SCALAR_ARGS = dict(B=BATCH_SIZE, H=NUM_HEADS, Sq=SEQ_LEN_Q, Sk=SEQ_LEN_K,
                   D=HEAD_DIM, scale=SCALE)
if not BACKWARD:
    SCALAR_ARGS['Hkv'] = NUM_KV_HEADS
if SPLIT:
    SCALAR_ARGS['num_splits'] = 8
TOLERANCES = {'atol': 0.004, 'rtol': 0.06, 'max_normalized_rms': 0.002,
              'per_output': {'lse': {'atol': 2e-4, 'rtol': 2e-5, 'max_normalized_rms': 2e-5}}}
CHECKED_OUTPUTS = ['dQ', 'dK', 'dV'] if BACKWARD else ['O', 'lse']
TIMING_STATISTIC = 'min'
HAS_CUDA_REFERENCE = True
REFERENCE_EXTRA_INCLUDES = ['reference_sources/flash_attn_v3',
                           'reference_sources/flash-attention/csrc/cutlass/include']
REFERENCE_EXTRA_CUDA_FLAGS = ['-gencode', 'arch=compute_90a,code=sm_90a']


def _blocks(q, k):
    # Bounded fp32 oracle: never allocate [B,H,Sq,Sk]. Disable TF32 rounding.
    torch.set_float32_matmul_precision('highest')
    for b in range(q.shape[0]):
        for h in range(q.shape[1]):
            kh = h // (NUM_HEADS // NUM_KV_HEADS)
            keys = k[b, kh].float()
            for start in range(0, q.shape[2], 128):
                end = min(start + 128, q.shape[2])
                scores = q[b, h, start:end].float() @ keys.T * SCALE
                if CAUSAL:
                    qi = torch.arange(start, end, device=q.device)[:, None]
                    ki = torch.arange(k.shape[2], device=q.device)[None, :]
                    scores.masked_fill_(ki > qi + k.shape[2] - q.shape[2], -float('inf'))
                yield b, h, kh, start, end, scores


def _forward(q, k, v):
    o = torch.empty_like(q)
    lse = torch.empty(q.shape[:-1], device=q.device, dtype=torch.float32)
    for b, h, kh, start, end, scores in _blocks(q, k):
        lse[b, h, start:end] = scores.logsumexp(-1)
        o[b, h, start:end] = (scores.softmax(-1) @ v[b, kh].float()).to(q.dtype)
    return o, lse


def get_inputs():
    shape = (BATCH_SIZE, NUM_HEADS, SEQ_LEN_Q, HEAD_DIM)
    kvshape = (BATCH_SIZE, NUM_KV_HEADS, SEQ_LEN_K, HEAD_DIM)
    # Larger logit range exercises online-softmax rescaling; fractional data
    # distinguishes native fp16/bf16 from FP8 approximations.
    q = torch.randn(shape, device='cuda', dtype=DTYPE) * 1.5
    k = torch.randn(kvshape, device='cuda', dtype=DTYPE) * 1.5
    v = torch.randn(kvshape, device='cuda', dtype=DTYPE)
    if SPLIT and CAUSAL:
        # Make ignoring a few forbidden tail keys observable even at 128K KV.
        k[:, :, -1, :] = q[:, ::NUM_HEADS//NUM_KV_HEADS, 0, :] * 1.5
    inputs = [('Q', q), ('K', k), ('V', v)]
    if BACKWARD:
        o, lse = _forward(q, k, v)
        inputs += [('O', o), ('dO', torch.randn_like(o)), ('lse', lse)]
    return inputs


def get_outputs(inputs):
    q, k, v = [t for _, t in inputs[:3]]
    if not BACKWARD:
        return [('O', torch.full_like(q, float('nan'))),
                ('lse', torch.full(q.shape[:-1], float('nan'), device=q.device))]
    sq_pad = (q.shape[2] + BLOCK_M - 1) // BLOCK_M * BLOCK_M
    return [('dQ', torch.full_like(q, float('nan'))),
            ('dK', torch.full_like(k, float('nan'))),
            ('dV', torch.full_like(v, float('nan'))),
            ('dsoftmax_sum', torch.empty(q.shape[0], q.shape[1], sq_pad,
                                        device=q.device, dtype=torch.float32)),
            ('dq_accum', torch.empty(q.shape[0], q.shape[1], sq_pad, HEAD_DIM,
                                    device=q.device, dtype=torch.float32))]


def reference_fn(inputs):
    q, k, v = [t for _, t in inputs[:3]]
    if not BACKWARD:
        o, lse = _forward(q, k, v)
        return [('O', o), ('lse', lse)]
    o, do, lse = [t for _, t in inputs[3:]]
    dq = torch.zeros_like(q, dtype=torch.float32)
    dk = torch.zeros_like(k, dtype=torch.float32)
    dv = torch.zeros_like(v, dtype=torch.float32)
    for b, h, kh, start, end, scores in _blocks(q, k):
        p = (scores - lse[b, h, start:end, None]).exp()
        grad = do[b, h, start:end].float()
        # Match the stated backward inputs, including the rounded forward O.
        delta = (grad * o[b, h, start:end].float()).sum(-1, keepdim=True)
        ds = p * (grad @ v[b, kh].float().T - delta) * SCALE
        dq[b, h, start:end] = ds @ k[b, kh].float()
        dk[b, kh] += ds.T @ q[b, h, start:end].float()
        dv[b, kh] += p.T @ grad
    return [('dQ', dq.to(q.dtype)), ('dK', dk.to(k.dtype)), ('dV', dv.to(v.dtype))]

DESCRIPTION = "Implement Hopper SM90 bwd attention, float16, head dimension 64.\nQ: contiguous [1, 16, 4096, 64]; K,V: contiguous [1, 16, 4096, 64].\nQuery head h uses KV head floor(h / (16//16)). O has Q's shape/dtype.\nCompute P = softmax(Q K^T / sqrt(64)), O = P V; non-causal (all keys visible).\nLSE is fp32 natural-log sum-exp, shape [B,H,Sq], not log2.\nReference and solution use cold L2 and the minimum of identical timing trials.\nAccumulate dot products and softmax in fp32. Do not quantize inputs to FP8.\nGiven O (rounded to float16), dO and natural-log LSE, compute dQ,dK,dV.\nUse delta = sum(dO * O) per row; dS = P * (dO V^T - delta).\ndQ = scale*dS*K; dK = scale*dS^T*Q; dV = P^T*dO.\nScratch dsoftmax_sum is [B,H,round_up(Sq,128)] fp32 and dq_accum is\n[B,H,round_up(Sq,128),D] fp32. Scratch contents on entry are unspecified;\nonly the three gradients are checked. All gradient elements must be written.\n\nRequired entry point:\nvoid launch_fa3_bwd(\n    const void* Q,\n    const void* K,\n    const void* V,\n    const void* O,\n    const void* dO,\n    void* dQ,\n    void* dK,\n    void* dV,\n    const float* lse,\n    float* dsoftmax_sum,\n    float* dq_accum,\n    int B,\n    int H,\n    int Sq,\n    int Sk,\n    int D,\n    float scale,\n    cudaStream_t stream\n);\n"
